def eval_expression(expr):
    """Computes the mathematical expression in expr, considering the order of operations,

    negative numbers, and raising ZeroDivisionError when dividing by zero.
    """
    # Remove all whitespace from the expression
    expr = "".join(expr.split())
    if not expr:
        return 0

    def parse_expression(s, index):
        node, index = parse_term(s, index)
        while index < len(s):
            if s[index] == "+":
                index += 1
                right, index = parse_term(s, index)
                node += right
            elif s[index] == "-":
                index += 1
                right, index = parse_term(s, index)
                node -= right
            else:
                break
        return node, index

    def parse_term(s, index):
        node, index = parse_factor(s, index)
        while index < len(s):
            if s[index] == "*":
                index += 1
                right, index = parse_factor(s, index)
                node *= right
            elif s[index] == "/":
                index += 1
                right, index = parse_factor(s, index)
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                node /= right
            else:
                break
        return node, index

    def parse_factor(s, index):
        if index >= len(s):
            raise ValueError("Unexpected end of expression")

        # Handle unary plus and minus (negative numbers)
        if s[index] == "+":
            return parse_factor(s, index + 1)
        if s[index] == "-":
            val, index = parse_factor(s, index + 1)
            return -val, index

        # Handle parentheses
        if s[index] == "(":
            index += 1
            val, index = parse_expression(s, index)
            if index >= len(s) or s[index] != ")":
                raise ValueError("Mismatched parentheses")
            return val, index + 1  # Skip the closing ')'

        # Handle numbers (integers and floats)
        start = index
        while index < len(s) and (s[index].isdigit() or s[index] == "."):
            index += 1

        if start == index:
            raise ValueError(f"Unexpected character at index {index}: {s[index]}")

        num_str = s[start:index]
        if "." in num_str:
            return float(num_str), index
        else:
            return int(num_str), index

    result, idx = parse_expression(expr, 0)
    if idx < len(expr):
        raise ValueError(f"Unexpected trailing characters at index {idx}")

    return result


# --- Examples ---
if __name__ == "__main__":
    print(eval_expression("3 + 4 * (2 - 1)"))  # Output: 7
    print(eval_expression("-5 + 2 * (-3)"))  # Output: -11
    print(eval_expression("10 / (5 - 5)"))  # Raises ZeroDivisionError
